CREATE TABLE agree_agreements (
  organization_id uuid NOT NULL,
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  agreement_number text NOT NULL,
  starts_on date NOT NULL,
  ends_on date NOT NULL,
  status text NOT NULL CHECK (status IN ('draft','active','expired','cancelled','review')),
  renewal_mode text NOT NULL CHECK (renewal_mode IN ('manual','automatic','none')),
  renewal_notice_days integer NOT NULL DEFAULT 30 CHECK (renewal_notice_days >= 0),
  interpretation_state text NOT NULL CHECK (interpretation_state IN ('unreviewed','approved','ambiguous','rejected')),
  interpretation_approved_at timestamptz,
  terms_snapshot text NOT NULL,
  customer_id uuid NOT NULL,
  plan_version_id uuid NOT NULL,
  source_file_id uuid,
  interpretation_reviewer_id uuid,
  PRIMARY KEY (organization_id,id),
  FOREIGN KEY (organization_id) REFERENCES org_organizations(id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,customer_id) REFERENCES crm_customers(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,plan_version_id) REFERENCES agree_plan_versions(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,source_file_id) REFERENCES crm_files(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,interpretation_reviewer_id) REFERENCES org_members(organization_id,id) ON DELETE RESTRICT,
  UNIQUE (organization_id,agreement_number),
  CHECK (ends_on >= starts_on),
  CHECK (interpretation_state <> 'approved' OR (interpretation_reviewer_id IS NOT NULL AND interpretation_approved_at IS NOT NULL))
);

CREATE INDEX ON agree_agreements (organization_id,customer_id);

CREATE INDEX ON agree_agreements (organization_id,plan_version_id);

