  FOREIGN KEY (organization_id,evidence_id) REFERENCES crm_files(organization_id,id) ON DELETE RESTRICT,
  CHECK (kind <> 'relocated' OR (from_property_id IS NOT NULL AND to_property_id IS NOT NULL AND from_property_id <> to_property_id)),
