CREATE TABLE agree_coverage (
  organization_id uuid NOT NULL,
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  scope_kind text NOT NULL CHECK (scope_kind IN ('property','equipment','trade')),
  service_scope text NOT NULL CHECK (service_scope IN ('all','specific')),
  valid_from date NOT NULL,
  valid_until date NOT NULL,
  review_state text NOT NULL CHECK (review_state IN ('approved','ambiguous','rejected')),
  agreement_id uuid NOT NULL,
  property_id uuid NOT NULL,
  equipment_id uuid,
  trade_id uuid,
  service_id uuid,
  PRIMARY KEY (organization_id,id),
  FOREIGN KEY (organization_id) REFERENCES org_organizations(id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,agreement_id) REFERENCES agree_agreements(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,property_id) REFERENCES crm_properties(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,equipment_id) REFERENCES crm_equipment(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,trade_id) REFERENCES org_trades(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,service_id) REFERENCES cat_services(organization_id,id) ON DELETE RESTRICT,
  CHECK ((scope_kind='property' AND equipment_id IS NULL AND trade_id IS NULL) OR (scope_kind='equipment' AND equipment_id IS NOT NULL AND trade_id IS NULL) OR (scope_kind='trade' AND trade_id IS NOT NULL AND equipment_id IS NULL)),
  CHECK ((service_scope='all' AND service_id IS NULL) OR (service_scope='specific' AND service_id IS NOT NULL)),
  CHECK (valid_until >= valid_from)
);

CREATE INDEX ON agree_coverage (organization_id,agreement_id);

CREATE INDEX ON agree_coverage (organization_id,property_id);

CREATE INDEX ON agree_coverage (organization_id,equipment_id);

CREATE INDEX ON agree_coverage (organization_id,trade_id);

CREATE INDEX ON agree_coverage (organization_id,service_id);

COMMENT ON TABLE agree_coverage IS 'Owner: agree. Mutable operational record; FK-restricted deletion. Every scope names a property. Explicit all/specific service scope; NULL never means wildcard on its own.';

