CREATE TABLE agree_benefit_ledger (
  organization_id uuid NOT NULL,
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  kind text NOT NULL CHECK (kind IN ('grant','consumption','expiration','reversal','adjustment')),
  quantity numeric(18,4) NOT NULL CHECK (quantity <> 0),
  occurred_at timestamptz NOT NULL,
  idempotency_key text NOT NULL,
  reason text NOT NULL,
  account_id uuid NOT NULL,
  job_id uuid,
  work_id uuid,
  source_record_id uuid,
  reverses_id uuid,
  approved_by uuid NOT NULL,
  PRIMARY KEY (organization_id,id),
  FOREIGN KEY (organization_id) REFERENCES org_organizations(id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,account_id) REFERENCES agree_benefit_accounts(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,job_id) REFERENCES job_jobs(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,work_id) REFERENCES job_confirmed_work(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,source_record_id) REFERENCES import_staging_records(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,reverses_id) REFERENCES agree_benefit_ledger(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,approved_by) REFERENCES org_members(organization_id,id) ON DELETE RESTRICT,
  UNIQUE (organization_id,idempotency_key),
  UNIQUE (organization_id,reverses_id),
  CHECK ((kind='grant' AND quantity>0) OR (kind IN ('consumption','expiration') AND quantity<0) OR kind IN ('reversal','adjustment')),
  CHECK ((kind='reversal') = (reverses_id IS NOT NULL)),
  CHECK (kind <> 'consumption' OR work_id IS NOT NULL)
);

CREATE INDEX ON agree_benefit_ledger (organization_id,account_id);

