CREATE TABLE inv_movements (
  organization_id uuid NOT NULL,
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  kind text NOT NULL CHECK (kind IN ('opening','receipt','transfer','consumption','usable_return','damaged_return','adjustment','reversal')),
  quantity numeric(18,4) NOT NULL CHECK (quantity > 0),
  unit_cost numeric(19,4) NOT NULL CHECK (unit_cost >= 0),
  currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  occurred_at timestamptz NOT NULL,
  idempotency_key text NOT NULL,
  reason text NOT NULL,
  material_id uuid NOT NULL,
  from_account_id uuid,
  to_account_id uuid,
  job_id uuid,
  work_id uuid,
  source_record_id uuid,
  reverses_id uuid,
  approved_by uuid NOT NULL,
  PRIMARY KEY (organization_id,id),
  FOREIGN KEY (organization_id) REFERENCES org_organizations(id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,material_id) REFERENCES cat_materials(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,from_account_id) REFERENCES inv_stock_accounts(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,to_account_id) REFERENCES inv_stock_accounts(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,job_id) REFERENCES job_jobs(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,work_id) REFERENCES job_confirmed_work(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,source_record_id) REFERENCES import_staging_records(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,reverses_id) REFERENCES inv_movements(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,approved_by) REFERENCES org_members(organization_id,id) ON DELETE RESTRICT,
  UNIQUE (organization_id,idempotency_key),
  UNIQUE (organization_id,reverses_id),
  CHECK (num_nonnulls(from_account_id,to_account_id) >= 1),
  CHECK (from_account_id IS NULL OR to_account_id IS NULL OR from_account_id <> to_account_id),
  CHECK (kind <> 'transfer' OR (from_account_id IS NOT NULL AND to_account_id IS NOT NULL)),
  CHECK (kind NOT IN ('opening','receipt','usable_return','damaged_return') OR (from_account_id IS NULL AND to_account_id IS NOT NULL)),
  CHECK (kind <> 'consumption' OR (from_account_id IS NOT NULL AND to_account_id IS NULL AND work_id IS NOT NULL)),
  CHECK ((kind='reversal') = (reverses_id IS NOT NULL)),
  CHECK (kind <> 'opening' OR source_record_id IS NOT NULL)
);

CREATE INDEX ON inv_movements (organization_id,material_id);

CREATE INDEX ON inv_movements (organization_id,from_account_id);

CREATE INDEX ON inv_movements (organization_id,to_account_id);

CREATE INDEX ON inv_movements (organization_id,job_id);

CREATE INDEX ON inv_movements (organization_id,work_id);

CREATE INDEX ON inv_movements (organization_id,source_record_id);

CREATE INDEX ON inv_movements (organization_id,reverses_id);

CREATE INDEX ON inv_movements (organization_id,approved_by);

COMMENT ON TABLE inv_movements IS 'Owner: inv. Append-only; a trigger rejects UPDATE/DELETE. Single row stores both legs of a transfer; equal quantity/cost by construction. Posted entries are append-only.';

