CREATE TABLE bill_invoice_lines (
  organization_id uuid NOT NULL,
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  position integer NOT NULL CHECK (position > 0),
  kind text NOT NULL CHECK (kind IN ('service','labor','material')),
  description text NOT NULL,
  quantity numeric(18,4) NOT NULL CHECK (quantity > 0),
  unit_price numeric(19,4) NOT NULL CHECK (unit_price >= 0),
  discount_amount numeric(19,2) NOT NULL DEFAULT 0 CHECK (discount_amount >= 0),
  tax_rate numeric(9,6) NOT NULL DEFAULT 0 CHECK (tax_rate BETWEEN 0 AND 1),
  tax_jurisdiction text NOT NULL,
  tax_amount numeric(19,2) NOT NULL CHECK (tax_amount >= 0),
  line_total numeric(19,2) NOT NULL CHECK (line_total >= 0),
  invoice_id uuid NOT NULL,
  unit_id uuid NOT NULL,
  service_id uuid,
  material_id uuid,
  price_version_id uuid,
  labor_rate_id uuid,
  work_id uuid,
  benefit_entry_id uuid,
  PRIMARY KEY (organization_id,id),
  FOREIGN KEY (organization_id) REFERENCES org_organizations(id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,invoice_id) REFERENCES bill_invoices(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,unit_id) REFERENCES cat_units(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,service_id) REFERENCES cat_services(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,material_id) REFERENCES cat_materials(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,price_version_id) REFERENCES cat_price_versions(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,labor_rate_id) REFERENCES cat_labor_rates(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,work_id) REFERENCES job_confirmed_work(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,benefit_entry_id) REFERENCES agree_benefit_ledger(organization_id,id) ON DELETE RESTRICT,
  UNIQUE (organization_id,invoice_id,position),
  CHECK (discount_amount <= round(quantity*unit_price,2)),
  CHECK (tax_amount = round((round(quantity*unit_price,2)-discount_amount)*tax_rate,2)),
  CHECK (line_total = round(quantity*unit_price,2)-discount_amount+tax_amount)
);

CREATE INDEX ON bill_invoice_lines (organization_id,invoice_id);

CREATE INDEX ON bill_invoice_lines (organization_id,unit_id);

CREATE INDEX ON bill_invoice_lines (organization_id,service_id);

CREATE INDEX ON bill_invoice_lines (organization_id,material_id);

CREATE INDEX ON bill_invoice_lines (organization_id,price_version_id);

CREATE INDEX ON bill_invoice_lines (organization_id,labor_rate_id);

CREATE INDEX ON bill_invoice_lines (organization_id,work_id);

CREATE INDEX ON bill_invoice_lines (organization_id,benefit_entry_id);

COMMENT ON TABLE bill_invoice_lines IS 'Owner: bill. Mutable operational record; FK-restricted deletion. ';

