  resolution text,
  resolved_at timestamptz,
  invoice_id uuid NOT NULL,
  line_id uuid,
  evidence_file_id uuid,
  evidence_work_id uuid,
  reviewer_id uuid,
  PRIMARY KEY (organization_id,id),
  FOREIGN KEY (organization_id) REFERENCES org_organizations(id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,invoice_id) REFERENCES bill_invoices(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,line_id) REFERENCES bill_invoice_lines(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,evidence_file_id) REFERENCES crm_files(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,evidence_work_id) REFERENCES job_confirmed_work(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,reviewer_id) REFERENCES org_members(organization_id,id) ON DELETE RESTRICT,
  CHECK (status = 'open' OR (resolution IS NOT NULL AND resolved_at IS NOT NULL AND reviewer_id IS NOT NULL))
);

CREATE INDEX ON bill_review_flags (organization_id,invoice_id);

CREATE INDEX ON bill_review_flags (organization_id,line_id);

CREATE INDEX ON bill_review_flags (organization_id,evidence_file_id);

CREATE INDEX ON bill_review_flags (organization_id,evidence_work_id);

CREATE INDEX ON bill_review_flags (organization_id,reviewer_id);

COMMENT ON TABLE bill_review_flags IS 'Owner: bill. Mutable operational record; FK-restricted deletion. ';

CREATE TABLE bill_corrections (
  organization_id uuid NOT NULL,
  id uuid NOT NULL DEFAULT gen_random_uuid(),
  created_at timestamptz NOT NULL DEFAULT now(),
  kind text NOT NULL CHECK (kind IN ('credit','correction')),
  amount numeric(19,2) NOT NULL CHECK (amount <> 0),
  currency text NOT NULL CHECK (currency ~ '^[A-Z]{3}$'),
  reason text NOT NULL,
  issued_at timestamptz NOT NULL,
  line_snapshot jsonb NOT NULL,
  idempotency_key text NOT NULL,
  issued_snapshot_id uuid NOT NULL,
  approved_by uuid NOT NULL,
  PRIMARY KEY (organization_id,id),
  FOREIGN KEY (organization_id) REFERENCES org_organizations(id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,issued_snapshot_id) REFERENCES bill_issued_snapshots(organization_id,id) ON DELETE RESTRICT,
  FOREIGN KEY (organization_id,approved_by) REFERENCES org_members(organization_id,id) ON DELETE RESTRICT,
  UNIQUE (organization_id,idempotency_key)
);

CREATE INDEX ON bill_corrections (organization_id,issued_snapshot_id);

CREATE INDEX ON bill_corrections (organization_id,approved_by);

COMMENT ON TABLE bill_corrections IS 'Owner: bill. Append-only; a trigger rejects UPDATE/DELETE. ';

CREATE INDEX ON report_events (organization_id,occurred_at DESC,event_type);

CREATE INDEX ON audit_events (organization_id,record_table,record_id,occurred_at DESC);

CREATE INDEX ON job_appointments (organization_id,starts_at) WHERE status='scheduled';

CREATE INDEX ON follow_tasks (organization_id,due_at) WHERE status='open';

CREATE INDEX ON agree_benefit_reservations (organization_id,account_id) WHERE status='active';

CREATE INDEX ON inv_reservations (organization_id,account_id) WHERE status='active';
